func NewOutputsValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (OutputsValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing OutputsValue Attribute Value",
				"While creating a OutputsValue value, a missing attribute value was detected. "+
					"A OutputsValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("OutputsValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid OutputsValue Attribute Type",
				"While creating a OutputsValue value, an invalid attribute value was detected. "+
					"A OutputsValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("OutputsValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("OutputsValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra OutputsValue Attribute Value",
				"While creating a OutputsValue value, an extra attribute value was detected. "+
					"A OutputsValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra OutputsValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewOutputsValueUnknown(), diags
	}

	cardinalityAttribute, ok := attributes["cardinality"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`cardinality is missing from object`)

		return NewOutputsValueUnknown(), diags
	}

	cardinalityVal, ok := cardinalityAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`cardinality expected to be basetypes.StringValue, was: %T`, cardinalityAttribute))
	}

	descriptionAttribute, ok := attributes["description"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`description is missing from object`)

		return NewOutputsValueUnknown(), diags
	}

	descriptionVal, ok := descriptionAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`description expected to be basetypes.StringValue, was: %T`, descriptionAttribute))
	}

	nameAttribute, ok := attributes["name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`name is missing from object`)

		return NewOutputsValueUnknown(), diags
	}

	nameVal, ok := nameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`name expected to be basetypes.StringValue, was: %T`, nameAttribute))
	}

	portTypeAttribute, ok := attributes["port_type"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`port_type is missing from object`)

		return NewOutputsValueUnknown(), diags
	}

	portTypeVal, ok := portTypeAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`port_type expected to be basetypes.StringValue, was: %T`, portTypeAttribute))
	}

	requiredAttribute, ok := attributes["required"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`required is missing from object`)

		return NewOutputsValueUnknown(), diags
	}

	requiredVal, ok := requiredAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`required expected to be basetypes.BoolValue, was: %T`, requiredAttribute))
	}

	schemaIdAttribute, ok := attributes["schema_id"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`schema_id is missing from object`)

		return NewOutputsValueUnknown(), diags
	}

	schemaIdVal, ok := schemaIdAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`schema_id expected to be basetypes.StringValue, was: %T`, schemaIdAttribute))
	}

	if diags.HasError() {
		return NewOutputsValueUnknown(), diags
	}

	return OutputsValue{
		Cardinality: cardinalityVal,
		Description: descriptionVal,
		Name:        nameVal,
		PortType:    portTypeVal,
		Required:    requiredVal,
		SchemaId:    schemaIdVal,
		state:       attr.ValueStateKnown,
	}, diags
}

func NewOutputsValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) OutputsValue {
	object, diags := NewOutputsValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewOutputsValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t OutputsType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewOutputsValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewOutputsValueUnknown(), nil
	}

	if in.IsNull() {
		return NewOutputsValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewOutputsValueMust(OutputsValue{}.AttributeTypes(ctx), attributes), nil
}

func (t OutputsType) ValueType(ctx context.Context) attr.Value {
	return OutputsValue{}
}

var _ basetypes.ObjectValuable = OutputsValue{}

type OutputsValue struct {
	Cardinality basetypes.StringValue `tfsdk:"cardinality"`
	Description basetypes.StringValue `tfsdk:"description"`
	Name        basetypes.StringValue `tfsdk:"name"`
	PortType    basetypes.StringValue `tfsdk:"port_type"`
	Required    basetypes.BoolValue   `tfsdk:"required"`
	SchemaId    basetypes.StringValue `tfsdk:"schema_id"`
	state       attr.ValueState
}

func (v OutputsValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 6)

	var val tftypes.Value
	var err error

	attrTypes["cardinality"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["description"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["name"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["port_type"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["required"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["schema_id"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 6)

		val, err = v.Cardinality.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["cardinality"] = val

		val, err = v.Description.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["description"] = val

		val, err = v.Name.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["name"] = val

		val, err = v.PortType.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["port_type"] = val

		val, err = v.Required.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["required"] = val

		val, err = v.SchemaId.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["schema_id"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v OutputsValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v OutputsValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v OutputsValue) String() string {
	return "OutputsValue"
}

func (v OutputsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"cardinality": basetypes.StringType{},
		"description": basetypes.StringType{},
		"name":        basetypes.StringType{},
		"port_type":   basetypes.StringType{},
		"required":    basetypes.BoolType{},
		"schema_id":   basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"cardinality": v.Cardinality,
			"description": v.Description,
			"name":        v.Name,
			"port_type":   v.PortType,
			"required":    v.Required,
			"schema_id":   v.SchemaId,
		})

	return objVal, diags
}

func (v OutputsValue) Equal(o attr.Value) bool {
	other, ok := o.(OutputsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Cardinality.Equal(other.Cardinality) {
		return false
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.PortType.Equal(other.PortType) {
		return false
	}

	if !v.Required.Equal(other.Required) {
		return false
	}

	if !v.SchemaId.Equal(other.SchemaId) {
		return false
	}

	return true
}

func (v OutputsValue) Type(ctx context.Context) attr.Type {
	return OutputsType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

